    /// <summary>
    /// WPF OnStartup → host initialization, invoked by the Daqifi.Avalonia bootstrap from
    /// OnFrameworkInitializationCompleted. Wires the global exception handlers the WPF App
    /// ctor installed, builds the DI container, migrates the database, and shows MainWindow.
    /// </summary>
    // @port: Daqifi.Desktop.App.OnStartup
    public static void Initialize(IClassicDesktopStyleApplicationLifetime desktop)
    {
        // WPF ctor wiring: DispatcherUnhandledException → Dispatcher.UIThread.UnhandledException.
        Dispatcher.UIThread.UnhandledException += OnDispatcherUnhandledException;
        AppDomain.CurrentDomain.UnhandledException += OnUnhandledException;
        TaskScheduler.UnobservedTaskException += OnUnobservedTaskException;

        if (IsTestMode)
        {
            // Suppress any modal message boxes so UI automation is never blocked.
            FirewallConfiguration.SetMessageBoxService(new NoOpMessageBoxService());
        }

        ShowSplashScreen();

        Directory.CreateDirectory(DaqifiDataDirectory);
        AppDomain.CurrentDomain.SetData("DataDirectory", DaqifiDataDirectory);

        var serviceCollection = new ServiceCollection();
        serviceCollection.AddDbContextFactory<LoggingContext>(options =>
            options.UseSqlite($"Data source={DatabasePath}")
                .ConfigureWarnings(w => w.Ignore(RelationalEventId.PendingModelChangesWarning))
        );

        // Route Core's Microsoft.Extensions.Logging output (e.g. the firmware update service's
        // WiFi flash tool output / progress) into the desktop NLog file via AppLogger. Restrict
        // forwarding to DAQiFi/Core categories at Information+ so framework noise (EF Core,
        // HttpClient, etc.) doesn't flood DAQiFiAppLog.log and bury the flash diagnostics.
        serviceCollection.AddLogging(builder =>
        {
            builder.AddProvider(new AppLoggerLoggerProvider());
            // Scope the filter to this provider so it only governs what reaches the NLog file and
            // never suppresses logs for any other provider added later. Always surface Error+ from
            // any category (framework errors are worth keeping), plus DAQiFi/Core diagnostics at
            // Information+; non-DAQiFi informational noise (EF Core, HttpClient, …) is dropped.
            builder.AddFilter<AppLoggerLoggerProvider>((category, level) =>
                level is >= LogLevel.Error and < LogLevel.None
                || (category is not null
                    && category.StartsWith("Daqifi", StringComparison.OrdinalIgnoreCase)
                    && level is >= LogLevel.Information and < LogLevel.None));
        });

        serviceCollection.AddHttpClient();
        serviceCollection.AddSingleton<IFirmwareDownloadService>(provider =>
        {
            var httpClientFactory = provider.GetRequiredService<IHttpClientFactory>();
            return new GitHubFirmwareDownloadService(httpClientFactory.CreateClient());
        });
        // Widen the bootloader HID timeouts past Core's 10 s defaults so a long late flash op
        // doesn't trip the PIC32 update; see FirmwareUpdateServiceConfig / issue #575.
        serviceCollection.AddSingleton<IHidTransport>(_ => FirmwareUpdateServiceConfig.CreateBootloaderHidTransport());
        serviceCollection.AddSingleton<IExternalProcessRunner, ProcessExternalProcessRunner>();
        serviceCollection.AddSingleton<IFirmwareUpdateService>(provider => new FirmwareUpdateService(
            provider.GetRequiredService<IHidTransport>(),
            provider.GetRequiredService<IFirmwareDownloadService>(),
            provider.GetRequiredService<IExternalProcessRunner>(),
            provider.GetRequiredService<ILogger<FirmwareUpdateService>>(),
            options: FirmwareUpdateServiceConfig.CreateOptions()));
        // App-global bootloader watcher: discovers EVERY sitting HID bootloader and holds each one's
        // handle open (its own exclusive transport, keyed by device path) with a keep-alive read so
        // Windows USB selective-suspend can't wedge it before flashing (daqifi-nyquist-firmware#568).
        // The connection dialog binds to its list; the firmware dialog flashes a chosen one by path while
        // the others stay held. Each hold gets a FRESH transport (not the flasher's DI singleton) so
        // holding N devices never contends with the flasher or with each other.
        serviceCollection.AddSingleton<IBootloaderWatcher>(_ => new BootloaderWatcher(
            new HidBootloaderDiscovery(Common.Loggers.AppLogger.Instance),
            (devicePath, deviceName) => new BootloaderHoldService(
                FirmwareUpdateServiceConfig.CreateBootloaderHidTransport(),
                Common.Loggers.AppLogger.Instance,
                keepAliveReadTimeout: null,
                devicePath: devicePath,
                deviceName: deviceName),
            Common.Loggers.AppLogger.Instance));

        serviceCollection.AddSingleton<LoggingManager>();
        ServiceLocator.RegisterSingleton<IDialogService, DialogService.DialogService>();
        ServiceLocator.RegisterSingleton<IWindowViewModelMappings, WindowViewModelMappings>();

        ServiceProvider = serviceCollection.BuildServiceProvider();

        // Start holding any sitting HID bootloaders app-wide, right away — before the user opens the
        // connection dialog — so a device left in bootloader mode can't selective-suspend/wedge (#568)
        // while it waits. The watcher runs for the app's lifetime.
        //
        // Skipped in test/tooling mode (like the message-box service above): a headless/automation
        // boot has no reason to start hardware discovery, and Start() takes an *exclusive* HID handle
        // on any device sitting in bootloader mode. Gating the resolve too means the watcher (and its
        // HID discovery) is never even constructed under DAQIFI_TEST_MODE. (#18)
        if (!IsTestMode)
        {
            ServiceProvider.GetRequiredService<IBootloaderWatcher>().Start();
        }

        // Apply database migrations before any DB access.
        // Temporarily switch to OnExplicitShutdown so closing the migration
        // status window does not terminate the application.
        var contextFactory = ServiceProvider.GetRequiredService<IDbContextFactory<LoggingContext>>();
        if (DatabaseMigrator.PrepareMigration(contextFactory, DatabasePath))
        {
            desktop.ShutdownMode = ShutdownMode.OnExplicitShutdown;

            var statusWindow = new MigrationStatusWindow();
            statusWindow.Show();

            DatabaseMigrator.ApplyMigrations(contextFactory, DatabasePath);

            statusWindow.Close();

            desktop.ShutdownMode = ShutdownMode.OnLastWindowClose;
        }

        // The MainWindow ctor constructs DaqifiViewModel, whose one-time init is gated on the
        // host having started (upstream: Application.Current as App != null).
        IsStarted = true;

        // Create and show main window
        var view = new MainWindow();
        desktop.MainWindow = view;
        view.Show();

        AppLogger.Instance.AddBreadcrumb("app", "App startup complete");
    }

    /// <summary>
    /// Minimal host init for the MOBILE heads (Android/iOS). The desktop
    /// <see cref="Initialize"/> pulls in serial/HID/bootloader/WMI services and a
    /// MainWindow that don't exist on mobile; the shared pane ViewModels only need
    /// <see cref="ServiceProvider"/> to resolve an
    /// <c>IDbContextFactory&lt;LoggingContext&gt;</c> — LoggingManager.Instance's one
    /// constructor dependency — so this builds JUST that (a SQLite factory at the
    /// app-private data path) and applies the migrations without the desktop
    /// MigrationStatusWindow. Once it runs, the projected Channels/Profiles panes
    /// (which touch LoggingManager) construct on mobile instead of throwing.
    /// Downstream-only: no upstream counterpart (WPF is desktop-only). Idempotent.
    /// </summary>
    public static void InitializeMobile()
    {
        if (ServiceProvider is not null) { return; }   // already initialized

        // Whole-body guard: this runs from the mobile bootstrap, so a failure to
        // stand up the DI/SQLite layer must NOT crash the app boot — the Stream
        // tab needs no data layer, and panes that DO need it fall back to a
        // placeholder (MobileMainView.BuildPage). Leaving ServiceProvider null on
        // failure is the correct degraded state.
        try
        {
            try { Directory.CreateDirectory(DaqifiDataDirectory); } catch { /* best-effort */ }
            AppDomain.CurrentDomain.SetData("DataDirectory", DaqifiDataDirectory);

            var serviceCollection = new ServiceCollection();
            serviceCollection.AddDbContextFactory<LoggingContext>(options =>
                options.UseSqlite($"Data source={DatabasePath}")
                    .ConfigureWarnings(w => w.Ignore(RelationalEventId.PendingModelChangesWarning)));
            ServiceProvider = serviceCollection.BuildServiceProvider();

            // Apply migrations directly (no MigrationStatusWindow on mobile).
            // Inner guard: a migration failure still leaves ServiceProvider set, so
            // the pane ViewModels construct (LoggingManager.Instance needs only the
            // factory) — only DB-backed features degrade.
            try
            {
                var factory = ServiceProvider.GetRequiredService<IDbContextFactory<LoggingContext>>();
                using var context = factory.CreateDbContext();
                context.Database.Migrate();
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex, "Mobile database migration failed");
            }
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Mobile host init failed — data-layer panes will show a placeholder");
        }
    }

